// Regenerates images.ts: tiny synthetic JPEGs for the rolls tests, embedded as base64 because the tests
// run inside workerd, which can't read files. The GPS, serial and owner values are made up.
//   node test/fixtures/build.mjs
import { writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';

const require = createRequire(path.resolve(import.meta.dirname, '../../package.json'));
const sharp = require('sharp');

const canvas = (background) => sharp({ create: { width: 64, height: 48, channels: 3, background } }).jpeg({ quality: 80 });

const images = {
  // A Fujifilm frame shot at 23:42 local on 31 Oct, with every tag that must never leave the original.
  fuji: await canvas('#c84').withExif({
    IFD0: { Make: 'FUJIFILM', Model: 'X-T5' },
    IFD2: {
      DateTimeOriginal: '2026:10:31 23:42:03',
      OffsetTimeOriginal: '+05:30',
      FNumber: '28/10',
      ExposureTime: '1/250',
      ISOSpeedRatings: '400',
      FocalLength: '23/1',
      FocalLengthIn35mmFilm: '35',
      ExposureBiasValue: '-1/3',
      LensModel: 'XF23mmF1.4 R LM WR',
      BodySerialNumber: '9AB12345',
      CameraOwnerName: 'Test Owner',
    },
    IFD3: { GPSLatitudeRef: 'N', GPSLatitude: '15/1 1/1 0/1', GPSLongitudeRef: 'E', GPSLongitude: '73/1 58/1 0/1' },
  }).toBuffer(),
  // An iPhone frame with no offset tag: the date is read as +05:30.
  iphone: await canvas('#48c').withExif({
    IFD0: { Make: 'Apple', Model: 'iPhone 16 Pro' },
    IFD2: { DateTimeOriginal: '2026:11:02 07:15:00', FNumber: '178/100', ExposureTime: '1/120', ISOSpeedRatings: '64', FocalLength: '678/100', FocalLengthIn35mmFilm: '24' },
  }).toBuffer(),
  // A film scan: the scanner's EXIF, no date.
  scan: await canvas('#888').withExif({ IFD0: { Make: 'EPSON', Model: 'Perfection V600' }, IFD2: { ISOSpeedRatings: '100' } }).toBuffer(),
  // No EXIF at all.
  bare: await canvas('#2a2').toBuffer(),
};

const lines = Object.entries(images).map(([name, buf]) => `export const ${name} = '${buf.toString('base64')}';`);
writeFileSync(path.join(import.meta.dirname, 'images.ts'), `// Generated by build.mjs.\n${lines.join('\n')}\n`);
console.log(Object.fromEntries(Object.entries(images).map(([k, b]) => [k, b.length])));
